   SET EMIIMAP=#{emiimap}, EMIIMAPPORT=#{emiimapport}, EMISMTP=#{emismtp}, EMISMTPPORT=#{emismtpport}
     , EMIUSER=#{emiuser}, EMIPW=#{emipw}
 WHERE EMINO=#{emino} AND USERNO=#{userno}

